<?php
/** Proof — from a ticket, suggest and dismiss (spec "Proof", 3 and 4): ?from_ticket= prefills from public replies only (first names, no notes); saving writes created_from and a note; suggest → the link row and the note; dismiss removes the row. */
require __DIR__ . '/lib.php';
$W = world();
$owner = as_member(1); $marco = as_member(27); $lena = as_member(28);
$t = $W['t_jo'];
$number = q('SELECT number FROM tickets WHERE id = :t', ['t' => $t])[0]['number'];
q("INSERT INTO messages (ticket_id, kind, author_member_id, body_text) VALUES (:t, 'public_reply', 27, 'SMOKE answer: unplug the printer and count to ten.')", ['t' => $t]);
echo "1. From a ticket\n";
$r = page($lena, '/kb/admin/new?from_ticket=' . $number);
$body = $r['body'];
preg_match('/<textarea name="body"[^>]*>(.*?)<\/textarea>/s', $body, $m);
$text = html_entity_decode($m[1] ?? '', ENT_QUOTES);
ok($r['code'] === 200 && str_contains($body, 'value="SMOKE Printer on fire"'), 'the title is the subject');
ok(str_contains($text, 'it is on fire, help') && str_contains($text, 'unplug the printer'), 'the body quotes the public replies');
ok(!str_contains($text, 'check the fuse first'), "the fixture's internal note is absent");
ok(str_contains($text, '**SMOKE:**') && !str_contains($text, 'SMOKE Jo') && !str_contains($text, 'SMOKE Marco'), 'authors by first name only');
ok(str_contains($body, 'name="from_ticket" value="' . $t . '"'), 'the form carries from_ticket');
$since = last_activity_id();
[$c, $b] = act($lena, '/kb/admin/save.php', ['title' => 'SMOKE Printer on fire — what to do', 'body' => $text . "Unplug it.", 'visibility' => 'public', 'from_ticket' => $t, 'status' => 'published']);
$aid = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $aid > 0 && count(links_of($t, 'created_from')) === 1 && (int) links_of($t, 'created_from')[0]['article_id'] === $aid, 'saving wrote article_links (created_from)');
$note = q("SELECT body_text FROM messages WHERE ticket_id = :t AND kind = 'internal_note' ORDER BY id DESC LIMIT 1", ['t' => $t])[0]['body_text'];
ok(str_contains($note, 'Article written from this ticket: SMOKE Printer on fire — what to do'), 'and a note on the ticket naming the article');
$rows = activity('article.create', $since);
ok(count($rows) === 1 && (int) $rows[0]['ticket_id'] === $t && json_decode($rows[0]['after'], true)['from_ticket'] === $t, 'article.create logged with the ticket and from_ticket');
echo "2. Suggest and dismiss\n";
[$pub, $pubSlug] = mk_article($owner, 'SMOKE Printer basics', ['body' => 'SMOKE Printers need paper and toner.']);
$since = last_activity_id();
[$c, $b] = act($marco, '/kb/admin/link.php', ['ticket' => $t, 'article' => $pub]);
ok($c === 200 && count(links_of($t, 'suggested')) === 1 && ($b['article_id'] ?? 0) === $pub, 'article_suggest: the suggested link row');
$note = q("SELECT body_text FROM messages WHERE ticket_id = :t AND kind = 'internal_note' ORDER BY id DESC LIMIT 1", ['t' => $t])[0]['body_text'];
ok(str_contains($note, 'Suggested article: SMOKE Printer basics') && str_contains($note, '/kb/admin/' . $pub . '/edit'), 'and the internal note with the admin link');
ok(count(activity('article.suggest', $since)) === 1 && json_decode(activity('article.suggest', $since)[0]['after'], true)['article_id'] === $pub, 'article.suggest logged (after.article_id)');
$r = page($marco, '/tickets/' . $t);
ok(str_contains($r['body'], 'id="ticket-suggested-article-' . $pub . '"') && str_contains($r['body'], 'id="ticket-suggested-article-' . $pub . '-send"') && str_contains($r['body'], 'id="ticket-suggested-article-' . $pub . '-dismiss"'), 'the ticket page shows the suggestion with Send and Dismiss');
ok(str_contains($r['body'], 'id="ticket-reply-article-btn"'), 'the composer has the Article button');
$r = page($marco, '/kb/?picker=1&ticket=' . $t . '&q=printer');
ok($r['code'] === 200 && str_contains($r['body'], 'id="article-pick-' . $pub . '-suggest"') && str_contains($r['body'], 'id="article-pick-' . $pub . '-send"'), 'the picker searches and offers Suggest and Send');
[$c, $b] = act($marco, '/kb/admin/link.php', ['ticket' => $t, 'article' => $pub, 'remove' => 1]);
ok($c === 200 && links_of($t, 'suggested') === [], 'dismiss removes the link row');
ok(act(as_member(26), '/kb/admin/link.php', ['ticket' => $t, 'article' => $pub])[0] === 404 && act(as_member(29), '/kb/admin/link.php', ['ticket' => $W['t_jo2'], 'article' => $pub])[0] === 403, 'a requester who may not see the ticket: 404; a collaborator who follows it (no work right): 403');
[$int] = mk_article($owner, 'SMOKE Internal procedure', ['visibility' => 'internal']);
ok(act($marco, '/kb/admin/link.php', ['ticket' => $t, 'article' => $int])[0] === 200, 'an internal article may be suggested (a note, not a reply)');
exit($GLOBALS['fails'] === 0 ? 0 : 1);
